entries[56202] = { ["name"] = "Figur - Saphireule", ["text"] = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nTitanbarren (2), Himmelssaphir (2), Waldsmaragd\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nJuwelierskunst von Nordend (25)\nKosten:\n1\n\nFigur - Saphireule\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+2 Intelligenz\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 1 Vielseitigkeit\n\nBenutzen: Stellt im Verlauf von 12 Sek. 120 Mana wieder her. (5 Min Abklingzeit)\n28\nBenötigt Juwelierskunst von Nordend\n(25)" }
entries[56203] = { ["name"] = "Figur - Smaragdeber", ["text"] = "Wirken in 2.5 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nTitanbarren (2), Waldsmaragd (2), Scharlachrubin\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nJuwelierskunst von Nordend (25)\nKosten:\n1\n\nFigur - Smaragdeber\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+4 [Beweglichkeit oder Stärke]\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 1 Angriffskraft\n\nBenutzen: Beschwört einen Phantomeber, der 30 Sek. lang an Eurer Seite kämpft. (5 Min Abklingzeit)\n28\nBenötigt Juwelierskunst von Nordend\n(25)" }
