entries[56465] = { ["name"] = "Mechanische Schneebrille", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (8), Boreanisches Leder (2), Äonenschatten\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\nMechanische Schneebrille\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nHaltbarkeit 85 / 85\nAnlegen: Vor Kälte geschützt. Euer Frostwiderstand ist um 6 erhöht.\n24\nBenötigt Ingenieurskunst von Nordend\n(1)" }
entries[56466] = { ["name"] = "Überschallbooster", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (4), Eine Handvoll Kobaltbolzen (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\nÜberschallbooster\nWird beim Anlegen gebunden\nSchmuck\n+5 Ausdauer\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 14 . Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)\n24\nBenötigt Ingenieurskunst von Nordend\n(15)" }
entries[56467] = { ["name"] = "Lärmmaschine", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (2), Eine Handvoll Kobaltbolzen (8)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\nLärmmaschine\nWird beim Anlegen gebunden\nSchmuck\n+4 Intelligenz\nAnlegen: Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 6 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten. (Procchance: 50%, 50s Abklingzeit)\n24\nBenötigt Ingenieurskunst von Nordend\n(15)" }
